WITH parsed AS (SELECT id, host, log_ts, status_code, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, SHIFTRIGHT(status_code, 2) AS status_code_high, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version, SIZE(context) AS num_context, COALESCE(context['region'], 'direct') AS region_or_default FROM app_logs) SELECT host, DATE_TRUNC('DAY', log_ts) AS activity_day, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, COUNT(DISTINCT host) AS distinct_hosts, COUNT(DISTINCT id) AS distinct_ids FROM parsed GROUP BY 1, 2 ORDER BY distinct_ids ASC;
